function KeyboardInputSwitchable:__init()
    self.controller = nil

    self._lastFrameHasMoveInput = false -- bool
end


function KeyboardInputSwitchable:__delete()
end


function KeyboardInputSwitchable:Init( switchablePlayerController_, playerInputSwitcher_, isUseManualViwRotateInPCMode_ )

    self.playerInputSwitcher = playerInputSwitcher_


    if isUseManualViwRotateInPCMode_ == true then 
        Cursor.lockState = CursorLockMode.None
    else
        -- 锁定 鼠标锚点:
        Cursor.lockState = CursorLockMode.Locked
    end 


    -- must after Awake()
    self.mCamera = DreamSpaceCamera.GetMainCamera()
    assert( not isNull(self.mCamera:GetComponent(typeof(CinemachineBrain))) )
end    


function KeyboardInputSwitchable:OnDestroy()

    -- 解除 鼠标锚点锁定:
    Cursor.lockState = CursorLockMode.None

    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


-- =========================================== Self ================================================ --


function KeyboardInputSwitchable:SelfUpdate()

    -- ======== 移动键: ========
    local hasMoveInput = self:HasMoveInput()
    local v = Input.GetAxisRaw(KeyboardInfo.Vertical)
    local h = Input.GetAxisRaw(KeyboardInfo.Horizontal)

    if not self._lastFrameHasMoveInput and hasMoveInput then
        -- ===== MoveStart: =====
        InputManager.SetMoveInputFromDevice( Vector2.zero )
    end

    if self._lastFrameHasMoveInput and not hasMoveInput then
        -- ===== MoveEnd: =====
        InputManager.SetMoveInputFromDevice( Vector2.zero )
    end

    if hasMoveInput then
        -- ===== Move: =====
        local moveInput0 = Vector2( h,v )
        --InputManager.SetMoveInputFromDevice( moveInput0 )

        --- 
        local rawInput = Vector3(moveInput0.x, 0, moveInput0.y)
        local cameraPlanarRotation = self.playerInputSwitcher:CalculateCameraDirection(self.mCamera.transform.rotation)
        local moveInput = cameraPlanarRotation * rawInput

        InputManager.SetMoveInputFromDevice( moveInput )

    end
    self._lastFrameHasMoveInput = hasMoveInput

    -- ======== 其它键: ========

    for _, key in pairs(KeyboardInfo) do
        if type(key) ~= "string" and Input.GetKeyDown(key) and KeyboardInputMap.inputMap[key] then
            KeyboardInputMap.inputMap[key]()
        end
    end
    -- if Input.GetKeyDown(KeyboardInfo.CatEyeKey) then
