    -- end
end


function KeyboardInputSwitchable:HasMoveInput()
    local aDown = Input.GetKeyDown(KeyCode.A) -- todo: GetKey 好像已经包含了 GetKeyDown
    local a = Input.GetKey(KeyCode.A)
    local dDown = Input.GetKeyDown(KeyCode.D)
    local d = Input.GetKey(KeyCode.D)
    local wDown = Input.GetKeyDown(KeyCode.W)
    local w = Input.GetKey(KeyCode.W)
    local sDown = Input.GetKeyDown(KeyCode.S)
    local s = Input.GetKey(KeyCode.S)
    return aDown or a or dDown or d or wDown or w or sDown or s
end




return KeyboardInputSwitchable